declaration:
FUNCTION_BLOCK FB_Ipv4Parser

VAR_INPUT
  ipText : STRING(254);   
END_VAR
VAR_OUTPUT
  ipValue : UDINT;        
END_VAR
VAR
  ipv4WorkText : STRING(256);        
  n : INT;
  i : INT;
  ch : STRING(1);
  isDigit : BOOL;
  digit : INT;
  segLen : INT;           
  segVal : INT;           
  segZeroOnly : BOOL;     
  segCount : INT;         
  segments : ARRAY[0..3] OF INT;
  ok : BOOL;              
  run : BOOL;
END_VAR

implementation:
ipv4WorkText := CONCAT(ipText, '.');
n := LEN(ipv4WorkText);
ok := TRUE;
segCount := 0;
segLen := 0;
segVal := 0;
segZeroOnly := FALSE;


IF LEN(ipText) > 15 THEN
  ok := FALSE;
END_IF;


FOR i := 1 TO 16 DO
  run := ok AND (i <= n);
  IF run THEN
    ch := MID(ipv4WorkText, 1, i);
    isDigit := (ch >= '0') AND (ch <= '9');
    IF ch = '.' THEN
      IF segLen = 0 THEN
        ok := FALSE;            
      ELSIF segLen > 3 THEN
        ok := FALSE;            
      ELSIF segVal > 255 THEN
        ok := FALSE;            
      ELSIF segCount > 3 THEN
        ok := FALSE;            
      ELSE
        segments[segCount] := segVal;
        segCount := segCount + 1;
      END_IF;
      segLen := 0;
      segVal := 0;
      segZeroOnly := FALSE;
    ELSIF isDigit THEN
      digit := STRING_TO_INT(ch);
      IF (segLen = 0) AND (digit = 0) THEN
        segZeroOnly := TRUE;    
      ELSIF segZeroOnly THEN
        ok := FALSE;            
      END_IF;
      IF segLen < 3 THEN
        segLen := segLen + 1;
        segVal := segVal * 10 + digit;
      ELSE
        segLen := 4;            
      END_IF;
    ELSE
      ok := FALSE;              
    END_IF;
  END_IF;
END_FOR;


IF ok AND (segCount <> 4) THEN
  ok := FALSE;
END_IF;


ipValue := 0;
IF ok THEN
  FOR i := 0 TO 3 DO
    ipValue := ipValue * UDINT#256 + INT_TO_UDINT(segments[i]);
  END_FOR;
END_IF;
